type ThumbSide = "left" | "right";

type ThumbDataItem = {
  side: ThumbSide;
  bottom: number;
  rotate: number;
  w: number;
  h: number;
  opacity: number;
  delay: number;
};

const THUMB_DATA: ThumbDataItem[] = [
