  { side: "right", bottom: 600, rotate: 3, w: 660, h: 372, opacity: 0.22, delay: 20 },
  { side: "left", bottom: 280, rotate: 2, w: 560, h: 315, opacity: 0.18, delay: 34 },
];

const ThumbItem: React.FC<{ data: ThumbDataItem }> = ({ data }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const prog = spring({ frame, fps, delay: data.delay, config: { damping: 200 } });
  const xFrom = data.side === "left" ? -80 : 80;
  return (
    <div
      style={{
        position: "absolute",
        [data.side]: 60,
        bottom: data.bottom,
        width: data.w,
        height: data.h,
        borderRadius: 20,
        backgroundColor: "rgba(255,255,255,0.03)",
        border: "1.5px solid rgba(255,255,255,0.06)",
        opacity: interpolate(prog, [0, 1], [0, data.opacity]),
        transform: `translateX(${interpolate(prog, [0, 1], [xFrom, 0])}px) rotate(${data.rotate}deg)`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      <div style={{ fontSize: 80, opacity: 0.3, color: COLORS.white }}>▶</div>
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          right: 0,
          background: "linear-gradient(transparent, rgba(0,0,0,0.7))",
          padding: "48px 24px 16px",
